class Notebook:
    def __init__(self):
        self.__ligar : bool = False


    def getLigar(self):
        return self.__ligar

    def setLigar(self, valor : bool):
        self.__ligar = valor 
        return

    def Ligar(self):
        if not self.__ligar:
            self.ligar = True
            print("notebook ligado.")
        else:
            print("notebook já está ligado.")

    def desligar(self):
        if self.__ligar:
            self.__ligar = False
            print("notebook desligado")
        else:
            print("notebook ja esta desligado")

    def usar(self, temp : int):
        if self.__ligar:
            print(f"usado por {temp} minutos")
        else:
            print("fail: ligue o notebook primeiro")

    def mostrar(self):
        status = "ligar" if self.__ligar else "desligar"
        print(f"Status: {status}")



def main():
    pc = Notebook()

    while True:
        line = input()
        print("$" + line)
        args: list[args] = line.split()

        if args[0] == "end":
            break
        if args[0] == "mostrar":
            print(pc)
main()
